struct UiLanguage { const wchar_t* code; const wchar_t* name; const wchar_t* search; };
inline constexpr std::array<UiLanguage,10> uiLanguages{{
    {L"en-US",L"English",L"en"}, {L"pt-PT",L"Português",L"pt"},
    {L"es-ES",L"Español",L"es"}, {L"fr-FR",L"Français",L"fr"},
    {L"it-IT",L"Italiano",L"it"}, {L"de-DE",L"Deutsch",L"de"},
    {L"hi-IN",L"हिन्दी",L"hi"}, {L"zh-CN",L"简体中文",L"zh"},
    {L"nl-NL",L"Nederlands",L"nl"}, {L"nb-NO",L"Norsk bokmål",L"nb"}
}};
inline int languageIndex(std::wstring_view locale) {
    for(size_t i=0;i<uiLanguages.size();++i) if(locale==uiLanguages[i].code) return static_cast<int>(i);
    if(locale==L"zh-Hans")return 7;
    if(locale==L"no" || locale==L"no-NO")return 9;
    for(size_t i=0;i<uiLanguages.size();++i) if(locale==uiLanguages[i].search) return static_cast<int>(i);
    return 0;
}
inline const UiLanguage& languageAt(int index){return uiLanguages[static_cast<size_t>(index>=0 && index<static_cast<int>(uiLanguages.size())?index:0)];}
inline const wchar_t* uiFontFace(int language,bool semibold=false){
    if(language==6)return L"Nirmala UI";
    if(language==7)return L"Microsoft YaHei UI";
    return semibold?L"Segoe UI Semibold":L"Segoe UI";
}
inline std::vector<std::wstring> languageNames(){std::vector<std::wstring> out;out.reserve(uiLanguages.size());for(const auto& l:uiLanguages)out.emplace_back(l.name);return out;}
