inline const wchar_t* translate(int language,const wchar_t* english,const wchar_t* portuguese=nullptr) {
    if(language==0 || language<0 || language>=static_cast<int>(uiLanguages.size()))return english;
    if(language==1 && portuguese)return portuguese;
    const std::wstring_view key(english);
    const auto it=std::lower_bound(std::begin(uiMessages),std::end(uiMessages),key,[](const UiMessage& m,std::wstring_view k){return m.key<k;});
    if(it!=std::end(uiMessages) && it->key==key)return it->texts[static_cast<size_t>(language-1)];
    return english;
}
